//! Items inside an inline module (`mod name { ... }`): each one is generated by the generator of its kind.

use crate::analyzer::*;
use crate::parser::*;

use super::CodeGenerator;

impl<'ast> CodeGenerator<'ast> {
    /// Generate an item inside an inline module
    pub(crate) fn generate_inline_module_item(
        &mut self,
        item: &Item<'ast>,
        analyzed: &[AnalyzedFunction<'ast>],
    ) -> String {
        match item {
            Item::Function { decl, .. } => {
                // Find the analyzed version
                if let Some(analyzed_func) = analyzed.iter().find(|f| f.is_analysis_of(decl)) {
                    self.generate_function(analyzed_func)
                } else {
                    // Shouldn't happen, but generate basic signature
                    String::new()
                }
            }
            Item::Const { .. } | Item::Static { .. } => self.generate_const_or_static_item(item),
            Item::Struct { decl, .. } => self.generate_struct(decl),
            Item::Enum { decl, .. } => self.generate_enum(decl),
            Item::Trait { decl, .. } => self.generate_trait_with_analysis(decl, analyzed),
            Item::Impl { block, .. } => self.generate_impl(block, analyzed),
            Item::Mod {
                name,
                items,
                is_public,
                ..
            } => {
                // Nested inline module
                let mut output = format!("{}mod {} {{\n", if *is_public { "pub " } else { "" }, name);

                self.indent_level += 1;
                for nested_item in items {
                    output.push_str(&self.indent());
                    output.push_str(&self.generate_inline_module_item(nested_item, analyzed));
                }
                self.indent_level -= 1;

                output.push_str(&self.indent());
                output.push_str("}\n");
                output
            }
            Item::TypeAlias {
                name,
                type_params,
                target,
                is_pub,
                ..
            } => self.generate_type_alias(name, type_params, target, *is_pub),
            Item::Macro {
                doc_comment, expr, ..
            } => {
                let mut out = String::new();
                if let Some(doc) = doc_comment {
                    for line in doc.lines() {
                        out.push_str(&format!("// {}\n", line));
                    }
                }
                out.push_str(&self.generate_expression(expr));
                out.push('\n');
                out
            }
            // `pub use` inside an inline module: the re-export of `mod render { pub use super::mesh::generate }`.
            // Plain `use` lines inside inline modules are still derived, never emitted.
            Item::Use { path, alias, is_pub: true, .. } => self.generate_use(path, alias.as_deref(), true),
            _ => String::new(), // Ignore other items for now
        }
    }
}
